mapper.select:
SELECT  FROM knowledge_document
WHERE tenant_id = #{tenantId} AND owner_id = #{ownerId} AND document_id = #{id}
    AND lifecycle = 'ACTIVE'

SELECT  FROM knowledge_document
WHERE tenant_id = #{tenantId} AND owner_id = #{ownerId} AND active_content_hash = #{hash}
    AND lifecycle = 'ACTIVE' LIMIT 1

SELECT  FROM knowledge_document
WHERE tenant_id = #{tenantId} AND owner_id = #{ownerId} AND document_id > #{afterId}
    AND lifecycle = 'ACTIVE'
ORDER BY document_id ASC LIMIT #{limit}
